?><!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Activate Flix Town</title>
<style>body{font:16px system-ui;background:#090a0d;color:white;margin:0;min-height:100vh;display:grid;place-items:center}main{background:#171a20;padding:32px;border-radius:16px;width:min(400px,85vw)}h1{color:#e2303c}label{display:block;margin:18px 0 6px}input,button{box-sizing:border-box;width:100%;font:inherit;padding:12px;border-radius:7px}input{background:#222733;color:white;border:1px solid #495061}button{background:#c52230;color:white;border:0;margin-top:24px;cursor:pointer}#result{min-height:2em}</style>
<main><h1>Flix Town</h1><p>Enter the code shown on your TV and your account details.</p><form id="form"><label for="code">TV code</label><input id="code" inputmode="numeric" maxlength="8" pattern="[0-9]{8}" required value="<?= htmlspecialchars($code, ENT_QUOTES) ?>"><label for="user">Username</label><input id="user" autocomplete="username" required><label for="pass">Password</label><input id="pass" type="password" autocomplete="current-password" required><button>Activate TV</button></form><p id="result" role="status"></p></main>
<script>const endpoint='https://panelsandapps.com/panels/flixtown2027/api/pair-activate.php';document.querySelector('#form').addEventListener('submit',async e=>{e.preventDefault();let result=document.querySelector('#result');result.textContent='Checking account…';try{let r=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code:document.querySelector('#code').value,username:document.querySelector('#user').value,password:document.querySelector('#pass').value})});let data=await r.json();result.textContent=r.ok?'Your TV is activated. You can close this page.':data.error||'Activation failed';if(r.ok)document.querySelector('#pass').value=''}catch{result.textContent='Could not reach the activation service. Try again.'}})</script></html>
